package ru.zf.pravka.ui

import androidx.compose.ui.graphics.Color
import androidx.compose.ui.graphics.SolidColor
import androidx.compose.ui.graphics.vector.ImageVector
import androidx.compose.ui.graphics.vector.addPathNodes
import androidx.compose.ui.unit.dp

// Значки «как у Gemini» (версия 3, 26.09.2026, владелец: «может, попробуем
// иконки ещё в стиле Gemini?»). Это Material Symbols Rounded, вес 300: тот же
// почерк, что у Gemini и Android, — тонкий, со скруглёнными углами. Пути
// выписаны из google/material-design-icons (symbols/web/<имя>/
// materialsymbolsrounded/<имя>_wght300_24px.svg); Apache License 2.0,
// Copyright Google LLC. Библиотеку material-icons-extended не берём по той же
// причине, что и раньше (APK без R8): здесь только нужные шестьдесят с
// небольшим путей. Своих пар у Google нет только у «диска» — там наш знак
// тоньше (`Glyphs.pick`).
//
// Файл собран скриптом из скачанных SVG: новый значок — сначала выбрать имя в
// Material Symbols, потом дописать строку по образцу.

/** Путь значка Material: [big] — сетка 960 со сдвигом вверх, иначе старая сетка 24. */
internal class MsPath(val symbol: String, val big: Boolean, val paths: List<String>)

internal object GeminiGlyphs {

    private val cache = HashMap<String, ImageVector>()

    /** Значок по имени из `Glyphs` или null, если у Google пары нет. */
    fun vector(name: String): ImageVector? {
        val p = PATHS[name] ?: return null
        return cache.getOrPut(name) { build(name, p) }
    }

    private fun build(name: String, p: MsPath): ImageVector {
        val size = if (p.big) 960f else 24f
        return ImageVector.Builder(
            name = "Gemini.$name",
            defaultWidth = 24.dp,
            defaultHeight = 24.dp,
            viewportWidth = size,
            viewportHeight = size,
        ).apply {
            // Сетка Material Symbols — от 0 до 960 по x и от −960 до 0 по y.
            addGroup(translationY = if (p.big) 960f else 0f)
            for (d in p.paths) addPath(pathData = addPathNodes(d), fill = SolidColor(Color.Black))
            clearGroup()
        }.build()
    }

